def get_content():
    blocks = []
    blocks.append({"type": "pb"})
    blocks.append({"type": "h1", "text": "ВВЕДЕНИЕ"})
    
    # 1. Актуальность — расширенная версия
    blocks.append({"type": "p", "text": "Актуальность исследования. В современном информационном обществе объемы производимой и публикуемой научной информации растут экспоненциальными темпами. По оценкам наукометрических баз данных, таких как Web of Science, Scopus, eLibrary, ежегодный прирост числа научных статей составляет не менее 8–10%. Согласно статистике CrossRef, к 2025 году в мире ежегодно публикуется более 5 миллионов рецензируемых научных статей. В условиях такого информационного перенасыщения (информационного взрыва) перед исследователями, аналитиками и научными коллективами остро встает проблема эффективного поиска, навигации и систематизации релевантных тематических публикаций."})
    blocks.append({"type": "p", "text": "Традиционные поисковые системы и агрегаторы научной литературы в основном базируются на полнотекстовом индексе и библиографических метаданных (авторы, год, журнал, ключевые слова). Эти подходы, безусловно, эффективны для поиска конкретных статей по заданному запросу, однако они обладают рядом существенных ограничений. Во-первых, они не предоставляют пользователю визуального представления о семантической структуре предметной области. Во-вторых, традиционные методы поиска не позволяют автоматически выявлять скрытые взаимосвязи между публикациями, которые могут не иметь прямых цитирований или общих ключевых слов, но при этом концептуально близки по смыслу. В-третьих, процесс чтения и анализа найденных статей требует огромных временных затрат, поскольку пользователю приходится вручную просматривать полные тексты для извлечения главной сути."})
    blocks.append({"type": "p", "text": "В этой связи разработка автоматизированных интеллектуальных систем, способных не только индексировать тексты, но и самостоятельно извлекать семантические узлы (ключевые термины), собирать краткие реферативные аннотации из наиболее значимых предложений и строить многомерные графы связей, представляет собой весьма актуальную и востребованную задачу. Подобные системы способны трансформировать разрозненный массив текстовых документов в структурированную базу знаний, где каждая статья связана с другими публикациями через общность проблематики, методов или объектов исследования."})
    blocks.append({"type": "p", "text": "Внедрение методов обработки естественного языка (Natural Language Processing, NLP), основанных как на классических статистических моделях (TF-IDF, TextRank), так и на современных нейросетевых архитектурах (BERT, Sentence-Transformers), открывает принципиально новые возможности для семантического анализа текстов. Статистические алгоритмы обеспечивают вычислительную эффективность и прозрачность извлечения, тогда как нейросетевые модели способны улавливать глубинный контекст и синонимию терминов. Комбинирование этих подходов в рамках единого конвейера обработки (пайплайна) позволяет нивелировать недостатки каждого метода по отдельности и достичь высокой точности в задачах извлечения ключевых слов и автоматического реферирования."})
    blocks.append({"type": "p", "text": "Особую роль в решении поставленной задачи играют графовые базы данных, такие как Neo4j. В отличие от реляционных СУБД, графовые базы данных предназначены для эффективного хранения и обхода сложных сетей связей. Визуализация научных публикаций в виде интерактивного графа позволяет исследователям наглядно видеть кластеры тематически близких работ, обнаруживать ключевые термины-мосты, соединяющие разные предметные области, и отслеживать эволюцию научных идей."})
    blocks.append({"type": "p", "text": "Таким образом, тема настоящей выпускной квалификационной работы, посвященная построению графа терминов и аннотированию научных публикаций с использованием комплекса статистических и нейросетевых методов, является актуальной как с научно-исследовательской, так и с практической точек зрения."})

    # 2. Объект и предмет
    blocks.append({"type": "p", "text": "Объектом исследования выступает процесс автоматизированного интеллектуального анализа и структурирования текстовых корпусов научных публикаций на русском языке."})
    blocks.append({"type": "p", "text": "Предметом исследования являются алгоритмы, модели и программные методы автоматического извлечения ключевых терминов, экстрактивного реферирования и графового представления семантических связей в корпусе научных статей."})

    # 3. Цель
    blocks.append({"type": "p", "text": "Цель выпускной квалификационной работы заключается в разработке, программной реализации и оценке эффективности автоматизированной системы, предназначенной для извлечения ключевых слов, экстрактивной сборки аннотаций и построения семантического графа терминов и публикаций на основе совместного использования статистических и нейросетевых методов анализа текстов."})

    # 4. Задачи
    blocks.append({"type": "p", "text": "Для достижения поставленной цели были сформулированы и решены следующие взаимосвязанные задачи:", "indent": None})
    
    tasks = [
        "1. Провести всесторонний анализ предметной области, выявить существующие проблемы информационного поиска в наукометрических базах и обосновать необходимость применения графовых структур для систематизации научных знаний.",
        "2. Выполнить обзор и сравнительный анализ существующих методов извлечения ключевых слов (статистических, графовых, нейросетевых) и алгоритмов автоматического реферирования текстов, обосновать выбор конкретных алгоритмов.",
        "3. Разработать модульную архитектуру программного комплекса для поэтапной обработки документов (пайплайн), начиная от парсинга PDF-файлов и заканчивая экспортом данных в графовую СУБД.",
        "4. Спроектировать графовую модель данных, включающую узлы «Публикация» и «Термин», а также семантические и метрические связи между ними для последующей реализации в СУБД Neo4j.",
        "5. Программно реализовать алгоритмы парсинга PDF-файлов с интеллектуальным выделением метаданных (заголовок, авторская аннотация, авторские ключевые слова) и устранением артефактов переноса.",
        "6. Программно реализовать модуль извлечения ключевых слов, сочетающий метод частотного анализа (TF-IDF) и нейросетевой подход (KeyBERT) на базе трансформеров.",
        "7. Программно реализовать модуль экстрактивного реферирования на основе алгоритма MMR (Maximal Marginal Relevance) с учетом семантических весов ключевых слов.",
        "8. Осуществить интеграцию разработанных модулей с графовой базой данных Neo4j и разработать веб-интерфейс для интерактивной визуализации сети научных публикаций.",
        "9. Провести экспериментальное тестирование разработанной системы, выполнить количественную оценку точности извлечения терминов (Precision, Recall, F1-score) и качества собранных аннотаций (метрики семейства ROUGE)."
    ]
    for task in tasks:
        blocks.append({"type": "p", "text": task, "indent": None})

    # 5. Методы исследования
    blocks.append({"type": "p", "text": "Методы исследования. В работе применены методы системного анализа, теории графов, математической статистики, инженерии знаний, машинного обучения и обработки естественного языка (NLP). При разработке программного обеспечения использовались принципы объектно-ориентированного и функционального программирования, а также методы проектирования графовых баз данных. Для экспериментальной оценки качества разработанных алгоритмов применены стандартные метрики информационного поиска (Precision, Recall, F1-score) и автоматического реферирования (ROUGE-1, ROUGE-2, ROUGE-L)."})

    # 6. Новизна
    blocks.append({"type": "p", "text": "Научная новизна работы заключается в разработке комплексного подхода к анализу русскоязычных научных текстов, который объединяет классический метод частотного взвешивания (TF-IDF) с семантическими эмбеддингами нейросетевой языковой модели (KeyBERT). Впервые в рамках единого конвейера предложена архитектура, которая не только извлекает термины, но и использует их весовые коэффициенты для оптимизации функции предельной релевантности (MMR) при экстрактивной сборке рефератов, после чего формирует многомерный граф с учетом семантической близости терминов и индекса Жаккара для публикаций."})

    # 7. Практическая значимость
    blocks.append({"type": "p", "text": "Практическая значимость работы. Разработанный программный комплекс «Extra-Term-Graph» представляет собой готовое инструментальное средство, которое может быть использовано научными сотрудниками, аспирантами и аналитиками для автоматизации обзора литературы. Система включает интерактивный веб-интерфейс для визуализации графа публикаций и терминов, позволяющий исследователю наглядно видеть структуру терминологического аппарата, переходить между тематически близкими статьями и быстро ознакомиться с экстрактивной аннотацией без необходимости чтения полных текстов. Модульная архитектура позволяет легко расширять функциональность системы и интегрировать ее с другими корпоративными решениями."})

    # 8. Структура
    blocks.append({"type": "p", "text": "Структура и объем работы. Выпускная квалификационная работа состоит из введения, трех глав, заключения, списка использованных источников и приложений. Основной текст изложен на 55 страницах машинописного текста, включает 10 таблиц, формулы, листинги программного кода и графические иллюстрации. Список литературы содержит 30 наименований, в том числе 21 источник на иностранном языке."})
    blocks.append({"type": "pb"})

    return blocks
